    @ViewBuilder var content: Content
    var body: some View { content.environment(\.selectState, SelectState(value: $value)) }
}
struct Option: View {
    @Environment(\.selectState) private var state     // implicit, not a parameter
    var body: some View { Text("Option").onTapGesture { state?.value = "…" } }
