final class SelectViewController: UIViewController {   // parent owns the state
    private var options: [OptionViewController] = []
    private(set) var selected: String?

    func select(_ value: String) {                     // one owner, one invariant
        selected = value
        options.forEach { $0.isSelected = ($0.value == value) }
    }
}
